def start(self):
    """Start collecting statistics.

    Sets start time, the command line call, and the commands array to an empty list.
    Additionally, sets the kallisto and bustools paths and versions.
    """
    self.start_time = dt.datetime.now()
    self.call = ' '.join(sys.argv)
    self.commands = []
    self.workdir = os.getcwd()

    if not is_dry():
        # Import here to prevent circular imports
        from .utils import get_bustools_version, get_kallisto_version
        self.kallisto = {
            'path': get_kallisto_binary_path(),
            'version': '.'.join(str(i) for i in get_kallisto_version())
        }
        self.bustools = {
            'path': get_bustools_binary_path(),
            'version': '.'.join(str(i) for i in get_bustools_version())
        }

def bin_query(self, table, chrom, start, end):
    """
    perform an efficient spatial query using the bin column if available.
    The possible bins are calculated from the `start` and `end` sent to
    this function.

    Parameters
    ----------

    table : str or table
       table to query

    chrom : str
       chromosome for the query

    start : int
       0-based start postion

    end : int
        0-based end position

    """
    if isinstance(table, six.string_types):
        table = getattr(self, table)

    try:
        tbl = table._table
    except AttributeError:
        tbl = table.column_descriptions[0]['type']._table

    q = table.filter(tbl.c.chrom == chrom)

    if hasattr(tbl.c, "bin"):
        bins = Genome.bins(start, end)
        if len(bins) < 100:
            q = q.filter(tbl.c.bin.in_(bins))

    if hasattr(tbl.c, "txStart"):
        return q.filter(tbl.c.txStart <= end).filter(tbl.c.txEnd >= start)
    return q.filter(tbl.c.chromStart <= end).filter(tbl.c.chromEnd >= start)

def is_gene_pred(self):
    """
    http://genome.ucsc.edu/FAQ/FAQformat.html#format9
    """
    return hasattr(self, "exonStarts") or hasattr(self, 'chromStarts')

def parse_dot_rmats(dot_rmats_path):
    if not os.path.isfile(dot_rmats_path):
        return None, '{} is not a valid filepath'.format(dot_rmats_path)

    with open(dot_rmats_path, 'rt') as f_handle:
        bam_line = f_handle.readline()
        bams = bam_line.strip().split(',')

        read_length, error = _parse_int_line(f_handle)
        if error:
            return None, error

        novel_juncs, error = _parse_by_gene_by_bam_section(
            bams, f_handle, _parse_novel_junc)
        if error:
            return None, error

        exons, error = _parse_by_gene_by_bam_section(bams, f_handle,
                                                     _parse_exons)
        if error:
            return None, error

        multis, error = _parse_by_gene_by_bam_section(bams, f_handle,
                                                      _parse_multis)
        if error:
            return None, error

    return {
        'bams': bams,
        'read_length': read_length,
        'novel_juncs': novel_juncs,
        'exons': exons,
        'multis': multis
    }, None

def _correct_mut_counts(self, populations, tree_idx):
  for sidx, subclone in populations.items():
    # Note that only mutass entries for subclones with (> 0 SSMs or > 0
    # CNVs) will exist. Thus, no mutass entry will exist for node 0, as it
    # never has SSMs or CNVs.
    if sidx == 0:
      continue
    for mut_type in ('ssms', 'cnvs'):
      subclone['num_%s' % mut_type] = len(self._mutass[tree_idx][sidx][mut_type])

