def execute(self, worker: 'SnifflesWorker' = None) -> Optional[GenotypeResult]:
    config = self.config

    qc = False
    _, read_count = self.build_leadtab()
    svcandidates = self.call_candidates(qc, config=config)
    svcalls = self.finalize_candidates(svcandidates, not qc, config=config)

    binsize = 5000
    binedge = int(binsize / 10)
    genotype_svs_svtypes_bins = {svtype: {} for svtype in sv.TYPES}
    for genotype_sv in self.genotype_svs:
        genotype_sv.genotype_match_sv = None
        genotype_sv.genotype_match_dist = math.inf

        if genotype_sv.svtype not in genotype_svs_svtypes_bins:
            logging.getLogger('sniffles').warning(f'Unsupported SVTYPE: {genotype_sv.svtype}')
            continue

        bins = [int(genotype_sv.pos / binsize) * binsize]
        if genotype_sv.pos % binsize < binedge:
            bins.append((int(genotype_sv.pos / binsize) - 1) * binsize)
        if genotype_sv.pos % binsize > binsize - binedge:
            bins.append((int(genotype_sv.pos / binsize) + 1) * binsize)

        for bin in bins:
            if bin not in genotype_svs_svtypes_bins[genotype_sv.svtype]:
                genotype_svs_svtypes_bins[genotype_sv.svtype][bin] = []
            genotype_svs_svtypes_bins[genotype_sv.svtype][bin].append(genotype_sv)

    for cand in svcandidates:
        bin = int(cand.pos / binsize) * binsize
        if bin not in genotype_svs_svtypes_bins[cand.svtype]:
            continue
        if cand.svtype == "BND":
            for genotype_sv in genotype_svs_svtypes_bins[cand.svtype][bin]:
                dist = abs(genotype_sv.pos - cand.pos)
                # if minlen>0 and dist < genotype_sv.genotype_match_dist and dist <= config.cluster_merge_bnd * 2:
                if dist < genotype_sv.genotype_match_dist and dist <= config.cluster_merge_bnd:
                    if cand.bnd_info.mate_contig == genotype_sv.bnd_info.mate_contig:
                        genotype_sv.genotype_match_sv = cand
                        genotype_sv.genotype_match_dist = dist
        else:
            for genotype_sv in genotype_svs_svtypes_bins[cand.svtype][bin]:
                dist = abs(genotype_sv.pos - cand.pos) + abs(abs(genotype_sv.svlen) - abs(cand.svlen))
                minlen = float(min(abs(genotype_sv.svlen), abs(cand.svlen)))
                if minlen > 0 and dist < genotype_sv.genotype_match_dist and dist <= config.combine_match * math.sqrt(
                        minlen) and dist <= config.combine_match_max:
                    genotype_sv.genotype_match_sv = cand
                    genotype_sv.genotype_match_dist = dist

    postprocessing.coverage(self.genotype_svs, self.lead_provider, config)

    # Determine genotypes for unmatched input SVs
    for svcall in self.genotype_svs:
        coverage_list = [svcall.coverage_start, svcall.coverage_center, svcall.coverage_end]
        coverage_list = [c for c in coverage_list if c is not None]
        if len(coverage_list) == 0:
            return
        coverage = round(sum(coverage_list) / len(coverage_list))
        svcall.genotypes = {}
        if coverage > 0:
            svcall.genotypes[0] = (0, 0, 0, coverage, 0, (None, None))
        else:
            svcall.genotypes[0] = config.genotype_none

    from sniffles.result import GenotypeResult
    return GenotypeResult(self, self.genotype_svs, read_count)

def curvature_method1(a: np.array, v: np.array) -> float:
    """https://link.springer.com/article/10.1007/s12650-018-0474-6"""
    if v.ndim == 1:
        v = v[:, None]
    kappa = np.linalg.norm(np.outer(v, a)) / np.linalg.norm(v) ** 3

    return kappa

def resample_hypers(self, dp_alpha=True, alpha_decay=True, dp_gamma=True):

    def dp_alpha_llh(dp_alpha, alpha_decay):
        def descend(dp_alpha, root, depth=0):
            llh = betapdfln(root['main'], 1.0,
                            (alpha_decay ** depth) * dp_alpha) if self.min_depth <= depth else 0.0
            for child in root['children']:
                llh += descend(dp_alpha, child, depth + 1)
            return llh

        return descend(dp_alpha, self.root)

    if dp_alpha:
        upper = self.max_dp_alpha
        lower = self.min_dp_alpha
        llh_s = log(rand()) + dp_alpha_llh(self.dp_alpha, self.alpha_decay)
        while True:
            new_dp_alpha = (upper - lower) * rand() + lower
            new_llh = dp_alpha_llh(new_dp_alpha, self.alpha_decay)
            if new_llh > llh_s:
                break
            elif new_dp_alpha < self.dp_alpha:
                lower = new_dp_alpha
            elif new_dp_alpha > self.dp_alpha:
                upper = new_dp_alpha
            else:
                raise Exception("Slice sampler shrank to zero!")
        self.dp_alpha = new_dp_alpha

    if alpha_decay:
        upper = self.max_alpha_decay
        lower = self.min_alpha_decay
        llh_s = log(rand()) + dp_alpha_llh(self.dp_alpha, self.alpha_decay)
        while True:
            new_alpha_decay = (upper - lower) * rand() + lower
            new_llh = dp_alpha_llh(self.dp_alpha, new_alpha_decay)
            if new_llh > llh_s:
                break
            elif new_alpha_decay < self.alpha_decay:
                lower = new_alpha_decay
            elif new_alpha_decay > self.alpha_decay:
                upper = new_alpha_decay
            else:
                raise Exception("Slice sampler shrank to zero!")
        self.alpha_decay = new_alpha_decay

    def dp_gamma_llh(dp_gamma):
        def descend(dp_gamma, root):
            llh = 0
            for i, child in enumerate(root['children']):
                llh += betapdfln(root['sticks'][i], 1.0, dp_gamma)
                llh += descend(dp_gamma, child)
            return llh

        return descend(dp_gamma, self.root)

    if dp_gamma:
        upper = self.max_dp_gamma
        lower = self.min_dp_gamma
        llh_s = log(rand()) + dp_gamma_llh(self.dp_gamma)
        while True:
            new_dp_gamma = (upper - lower) * rand() + lower
            new_llh = dp_gamma_llh(new_dp_gamma)
            if new_llh > llh_s:
                break
            elif new_dp_gamma < self.dp_gamma:
                lower = new_dp_gamma
            elif new_dp_gamma > self.dp_gamma:
                upper = new_dp_gamma
            else:
                raise Exception("Slice sampler shrank to zero!")
        self.dp_gamma = new_dp_gamma

def identify_cluster_ATAC(adata, cell_type, cell_type_markers, peak_promoter_file, gene_name_pos=5, path='', n_peaks_per_cluster=1000):

    peak_name = []
    gene_name = []
    with open(path+peak_promoter_file) as f:
        head = f.readline()
        for line in f:
            line = line.split("\t")
            peak_name.append(line[0])
            gene_name.append(line[gene_name_pos].upper())

    matching_peaks = []
    matching_gene_name = []
    for i in range(0,len(peak_name)):
        # check if peak is in the adata object and if the according gene name is a marker
        if peak_name[i] in list(adata.var_names) and gene_name[i] in cell_type_markers[cell_type]:
            matching_peaks.append(peak_name[i])
            matching_gene_name.append(gene_name[i])
    # get the cell type names per matching peak
    cell_type_peaks = {}
    cell_type_peaks[cell_type] = []
    for j in range(0,len(matching_peaks)):
        if matching_gene_name[j] in cell_type_markers[cell_type]:
            cell_type_peaks[cell_type].append(matching_peaks[j]+"_"+matching_gene_name[j])

    # make the peaks unique
    cell_type_peaks[cell_type] = list(set(cell_type_peaks[cell_type]))


    cell_type_peak = []
    cell_type_gene = []
    for elem in cell_type_peaks[cell_type]:
        ctype = elem.split("_")
        cell_type_peak.append(ctype[0]+"_"+ctype[1]+"_"+ctype[2])
        cell_type_gene.append(ctype[3])

    sc.tl.rank_genes_groups(adata, groupby="louvain", n_genes=n_peaks_per_cluster)

    # top 100 to 1000 ranked peaks per louvain group
    ATAC_ranking_dict = {}
    for group in range(0, len(set(list(adata.obs["louvain"])))):
        ATAC_ranking_dict[str(group)] = []
        for idx in range(0,n_peaks_per_cluster):
            ATAC_ranking_dict[str(group)].append(list(adata.uns["rank_genes_groups"]['names'])[idx][group])

    sig_markers = []
    sig_peak = []
    for group in range(0, len(set(list(adata.obs["louvain"])))):
        for elem in ATAC_ranking_dict[str(group)]:
            if elem in cell_type_peak:
                sig_markers.append(elem+":"+str(group))
                sig_peak.append(elem)                

    if len(sig_markers) > 200:
        print("WARNING: found more than 200 marker peaks for your chosen cell type. Consider choosing a smaller number for n_peaks_per_cluster to reduce running time and get more significant results.")

    group_contribution = []
    for element in sig_markers:
        group = element.split(":")[1]
        group_contribution.append(group)

    most_prominent = max(set(group_contribution), key = group_contribution.count) 

    print("Differentially open peaks in promoters for known",cell_type,"marker genes are most prominently found in louvain group",most_prominent)

    # only take unique peaks (peaks can be among top markers in more than one group)
    unique_sig_peaks = []
    sig_gene_names = []
    for idx,name in enumerate(cell_type_peak):
        if name in sig_peak:
            sig_gene_names.append(cell_type_gene[idx])
            unique_sig_peaks.append(cell_type_peak[idx])

    return(sc.pl.umap(adata, color=unique_sig_peaks, title=sig_gene_names))

