def _get_samples(v):
    import numpy as np

    def _get_gt(s):
        if not ":" in s:
            return 2
        s = s.split(":", 1)[0]
        if s in ("0/0", "0|0", "0/.", "./0", "0|."):
            return 0
        if s in ("0/1", "0|1", "1/.", "./1", "1/."):
            return 1
        if s in ("1/1", "1|1"):
            return 3
        return 2
    toks = _get_line_for(v)
    samples = toks[9:]
    return np.array([_get_gt(s) for s in samples], np.int32)

def siblings(self):
    sibs = []
    for parent in (self.mom, self.dad):
        if parent is UNKNOWN: continue
        sibs.extend(x for x in parent.kids if x not in sibs and x != self)
    return sibs

