def calc_reference_sas(
    adata: ad.AnnData,
    batch_effect: str = "dataset_name",
    cell_ontology: str = "cell_ontology_class",
    similarity: typing.Callable = _identity,
):
    neighbors_propotion = []
    n = len(adata.obs[batch_effect].unique())
    for x in adata.obs[batch_effect].unique():
        propotion = 0
        for i in adata.obs[cell_ontology].unique():
            neighbors = 0
            own_neighbors = 0
            for j in adata.obs[cell_ontology].unique():
                own_neighbors += (
                    similarity(i, j)
                    * (
                        (adata.obs[cell_ontology] == j) & (adata.obs[batch_effect] == x)
                    ).sum()
                )
                neighbors += similarity(i, j) * (adata.obs[cell_ontology] == j).sum()

            propotion += (
                own_neighbors
                / neighbors
                * (
                    (adata.obs[cell_ontology] == i) & (adata.obs[batch_effect] == x)
                ).sum()
            )

        propotion = propotion / (adata.obs[batch_effect] == x).sum()
        neighbors_propotion.append(propotion)
    neighbors_propotion = np.mean(neighbors_propotion)
    return 1 - (neighbors_propotion - 1 / n) / (1 - 1 / n)

def Get_prior_allele_mat(self, read_smpl_count, alt_smpl_count, cell_no_threshold, total_depth, Alt_freq, pe):
    if ((read_smpl_count > cell_no_threshold - 1) & (alt_smpl_count == 1)):
        prior_allele_mat = allele_prior(0.2)
    elif ((read_smpl_count > cell_no_threshold) & (alt_smpl_count == 2) & (total_depth > 30) & (Alt_freq < 0.1)):
        prior_allele_mat = allele_prior(0.1)
    else:
        prior_allele_mat = allele_prior(pe)
    return prior_allele_mat

def __call__(self, loss):
    if not hasattr(self, 'layer'):
        raise Exception('Need to call `set_layer` on '
                        'ActivityRegularizer instance '
                        'before calling the instance.')
    regularized_loss = loss
    for i in range(len(self.layer.inbound_nodes)):
        output = K.sigmoid(0.1 * self.layer.get_output_at(i))
        #output = self.layer.get_output_at(i)
        p_hat = K.mean(K.abs(output))
        regularized_loss += self.l * kl_divergence(self.p, p_hat)
    return K.in_train_phase(regularized_loss, loss)

