def get_volume(
    batch: np.ndarray,
    num_batch: int,
    cluster: np.ndarray,
    sum_cluster: int,
    num_clusters: typing.List[int],
):
    volume = np.zeros(sum_cluster)
    for i in range(num_batch):
        for j in range(num_clusters[i], num_clusters[i + 1]):
            volume[j] = (cluster == j).sum() / (batch == i).sum()

    return volume

