    strand_map = {}
    qual = 0.0

    [ SU, PE, SR ] = [0,0,0]

    s_name_list = []
    s1_name_list = []

    format_string = var.get_format_string()
    gt_dict = dict()

    for b_i in c:
        A = BP[b_i].l.rstrip().split('\t')
        if A[5].isdigit():
            qual += float(A[5])

        m = l_bp.to_map(A[7])

        for strand_entry in m['STRANDS'].split(','):
            s_type,s_count = strand_entry.split(':')
            if s_type not in strand_map:
                strand_map[s_type] = 0
            strand_map[s_type] += int(s_count)

        SU += int(m['SU'])
        PE += int(m['PE'])
        SR += int(m['SR'])

        if 'SNAME' in m:
