def _fatal_errors(jerr):
    if jerr == 7777:
        raise ValueError(
            "All predictors have zero variance " "(glmnet error no. 7777)."
        )

    if jerr == 10000:
        raise ValueError(
            "At least one value of relative_penalties must be "
            "positive (glmnet error no. 10000)."
        )

    if jerr == 90000:
        raise ValueError("Solver did not converge (glmnet error no. 90000).")

    if jerr < 7777:
        raise RuntimeError(
            "Memory allocation error (glmnet error no. {}).".format(jerr)
        )

    if jerr > 8000 and jerr < 9000:
        k = jerr - 8000
        raise ValueError("Probability for class {} close to 0.".format(k))

    if jerr > 9000:
        k = jerr - 9000
        raise ValueError("Probability for class {} close to 1.".format(k))

    else:
        raise RuntimeError("Fatal glmnet error no. {}.".format(jerr))

def _closest2D(contactsA, contactsB, reportAAnnots, reportBAnnots):
    # our files are going to be given with [chr1 binStart1 binEnd1 chr2 binStart2 binEnd2]
    newPeaks = []
    # compare file 2 to file 1, meaning advance file 2 first
    for k in range(len(contactsB)):
        distance = -1
        closestFeature = []
        for i in range(len(contactsA)):

            chrA1 = contactsA[i][0]
            startA1 = contactsA[i][1]
            endA1 = contactsA[i][2]
            chrA2 = contactsA[i][3]
            startA2 = contactsA[i][4]
            endA2 = contactsA[i][5]
            annotA = contactsA[i][6]

            chrB1 = contactsB[k][0]
            startB1 = contactsB[k][1]
            endB1 = contactsB[k][2]
            chrB2 = contactsB[k][3]
            startB2 = contactsB[k][4]
            endB2 = contactsB[k][5]
            annotB = contactsB[k][6]

            if chrA1 != chrB1 or chrA2 != chrB2:
                continue
            else:
                if startA1 < startB1 and endA1 < startB1:
                    bin1Dist = startB1 - endA1
                elif startB1 < startA1 and endB1 < startA1:
                    bin1Dist = startA1 - endB1
                else:
                    bin1Dist = 0
                if startA2 < startB2 and endA2 < startB2:
                    bin2Dist = startB2 - endA2
                elif startB2 < startA2 and endB2 < startA2:
                    bin2Dist = startA2 - endB2
                else:
                    bin2Dist = 0

                if bin1Dist + bin2Dist < distance or distance == -1:
                    distance = bin1Dist + bin2Dist
                    closestFeature = [i]
                elif bin1Dist + bin2Dist == distance:
                    closestFeature.append(i)

        if reportAAnnots:
            if reportBAnnots:
                annots = annotA[:]
                annots.extend(annotB)
            else:
                annots = annotA[:]
        else:
            if reportBAnnots:
                annots = annotB[:]
            else:
                annots = []
        if len(closestFeature) > 0:
            for cf in closestFeature:
                newPeaks.append([contactsB[k][:6], contactsA[cf][:6], distance, annots])
        else:
            newPeaks.append(
                [contactsB[k][:6], [".", ".", ".", ".", ".", "."], ".", annots]
            )

    return newPeaks

def build_leadtab(self):
    assert (self.lead_provider is None)

    config = self.config

    if config.input_is_cram and config.reference is not None:
        self.bam = pysam.AlignmentFile(config.input, config.input_mode, require_index=True, reference_filename=config.reference)
    else:
        self.bam = pysam.AlignmentFile(config.input, config.input_mode, require_index=True)
    self.lead_provider = leadprov.LeadProvider(config, self.id * config.task_read_id_offset_mult)
    externals = self.lead_provider.build_leadtab(self.regions if self.regions else [Region(self.contig, self.start, self.end)], self.bam)
    return externals, self.lead_provider.read_count

